// ImageBlock An image by `url`. The URL is the `url` of an image asset of this project (upload with
// createImageUpload and createImageAsset). Any other URL, including an image asset of another
// project, answers 400 VALIDATION_ERROR naming the field, unless the same document, resource or
// board already holds that URL in an image field. A `data:` or `blob:` URI answers 400
// VALIDATION_ERROR naming the field: documents hold no inline image data. Upload the image
// (createImageUpload, createImageAsset) and reference its URL. `fill: true` draws the image edge to
// edge with no frame or title, as the app's "Fill block" option does. It applies while
// `isTitleHidden` is true; an omitted `fill` reads as absent and draws the framed image. Carries
// `title`, the label above the block, and `isTitleHidden`, which hides that label and the frame
// around the block. A new one written without them reads `title: "Image"` and `isTitleHidden:
// true`; on a replace or an update an omitted `title` keeps the value the block already has. A
// block the app stored without `isTitleHidden` reads `isTitleHidden: true`, as the app draws it.
// Carries `layout` and `width`. A new one written without them is full width; on a replace or an
// update an omitted field keeps the value the block already has.
type ImageBlock struct {
	Alt           opt.Optional[string]      `json:"alt,omitzero"`
	Fill          opt.Optional[bool]        `json:"fill,omitzero"`
	ID            opt.Optional[string]      `json:"id,omitzero"`
	IsTitleHidden opt.Optional[bool]        `json:"isTitleHidden,omitzero"`
	Kind          ImageBlockKind            `json:"kind"`
	Layout        opt.Optional[BlockLayout] `json:"layout,omitzero"`
	Title         opt.Optional[string]      `json:"title,omitzero"`
	URL           string                    `json:"url"`
	// Width Block width as a percentage of the column it sits in, 10 to 100. It applies when `layout`
	// is not `default`.
	Width opt.Optional[int64] `json:"width,omitzero"`
}

