// PropertyBlock A sidebar or infobox property: a structured block kind plus the property envelope
// (`rank`, `title`, `isTitleHidden`, `isHidden`). A property the public model cannot express reads
// as `kind: "unsupported"` with its id and envelope. A property is laid out by the infobox or
// sidebar that holds it, so it carries neither `layout` nor `width`. Nesting through `children`,
// `rows` and filter `filters` is limited to 64 levels; deeper input answers 400 VALIDATION_ERROR.
type PropertyBlock struct {
	// Kind is the "kind" discriminator value.
	Kind string
	// Raw is the original JSON object.
	Raw json.RawMessage
}

// UnmarshalJSON records the discriminator and keeps the raw JSON.
func (u *PropertyBlock) UnmarshalJSON(b []byte) error {
	var d struct {
		V string `json:"kind"`
	}
	if err := json.Unmarshal(b, &d); err != nil {
		return err
	}
	u.Kind, u.Raw = d.V, append(json.RawMessage(nil), b...)
	return nil
}

// MarshalJSON returns the raw JSON unchanged.
func (u PropertyBlock) MarshalJSON() ([]byte, error) {
	if u.Raw == nil {
		return []byte("null"), nil
	}
	return u.Raw, nil
}

// PropertyBlockVariants maps each "kind" value to its variant type name.
var PropertyBlockVariants = map[string]string{
	"embed":              "EmbedProperty",
	"image":              "ImageProperty",
	"keyValue":           "KeyValueProperty",
	"map":                "MapProperty",
	"meter":              "MeterProperty",
	"resourceCollection": "ResourceCollectionProperty",
	"resourceLink":       "ResourceLinkProperty",
	"textField":          "TextFieldProperty",
	"unsupported":        "UnsupportedProperty",
}

// PropertyCreateRequest A property to create: `kind` plus that kind's fields, an optional `id`, the
