type ResourceMoveParams struct {
	// After Id of a sibling under the destination parent. The resource is placed directly after it.
	// Sending both `after` and `before` answers 400 VALIDATION_ERROR. An anchor that is not a child of
	// the destination parent answers 400 VALIDATION_ERROR; an unknown or deleted anchor answers 404
	// NOT_FOUND.
	After opt.Optional[string] `json:"after,omitzero"`
	// Before Id of a sibling under the destination parent. The resource is placed directly before it.
	// Sending both `after` and `before` answers 400 VALIDATION_ERROR. An anchor that is not a child of
	// the destination parent answers 400 VALIDATION_ERROR; an unknown or deleted anchor answers 404
	// NOT_FOUND.
	Before opt.Optional[string] `json:"before,omitzero"`
	// ParentID The new parent resource id, or null for the root. `templates` makes the resource a
	// top-level template; only a project admin may name it. Omitted, the resource stays under its
	// current parent. The resource itself or one of its descendants answers 400 VALIDATION_ERROR. An
	// unknown or deleted id answers 404 NOT_FOUND.
	ParentID opt.Nullable[string] `json:"parentId,omitzero"`
}

